import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../../core/supabase/supabase_service.dart';
import '../domain/models.dart';
import '../domain/souq_derb_repository.dart';

class SupabaseSouqDerbRepository implements SouqDerbRepository {
  final SupabaseService service; late SharedPreferences _prefs;
  SupabaseClient get _db=>service.client;
  SupabaseSouqDerbRepository(this.service);
  @override bool get isDemo=>false;
  @override Future<void> initialize() async{_prefs=await SharedPreferences.getInstance();}
  String _error(Object e)=>e is AuthException?_authMessage(e.message):e is PostgrestException?_dbMessage(e.message):'حدث خطأ غير متوقع. حاول مرة أخرى.';
  Never _throw(Object e)=>throw RepositoryException(_error(e));
  String _authMessage(String m){final l=m.toLowerCase();if(l.contains('invalid login'))return'البريد الإلكتروني أو كلمة المرور غير صحيحة';if(l.contains('already registered'))return'البريد الإلكتروني مسجل بالفعل';if(l.contains('email not confirmed'))return'أكد بريدك الإلكتروني أولًا';return m;}
  String _dbMessage(String m){if(m.contains('insufficient_stock'))return'الكمية المطلوبة غير متوفرة';if(m.contains('minimum_order'))return'لم تصل قيمة الطلب إلى الحد الأدنى';if(m.contains('store_unavailable'))return'المتجر مغلق أو لا يخدم منطقتك';return'تعذر تنفيذ العملية. حاول مرة أخرى.';}
  AppUser _user(Map<String,dynamic> j)=>AppUser(id:j['id'],fullName:j['full_name']??'',phone:j['phone']??'',email:j['email']??'',role:AppRole.values.byName(j['role']??'customer'),status:AccountStatus.values.byName(j['account_status']??'active'),serviceAreaId:j['service_area_id']);
  @override Future<AppUser?> currentUser() async{final u=service.currentUser;if(u==null)return null;try{final j=await _db.from('profiles').select().eq('id',u.id).maybeSingle();return j==null?null:_user(j);}catch(e){_throw(e);}}
  @override Future<AppUser> signIn(String email,String password)async{try{await service.signIn(email:email,password:password);final u=await currentUser();if(u==null)throw const RepositoryException('تعذر تحميل الملف الشخصي');return u;}catch(e){_throw(e);}}
  @override Future<AppUser> registerCustomer({required String name,required String phone,required String email,required String password,required String serviceAreaId})async{try{final r=await service.signUp(email:email,password:password,data:{'full_name':name,'phone':phone});if(r.user==null)throw const RepositoryException('فشل إنشاء الحساب');await _db.from('profiles').update({'full_name':name,'phone':phone,'service_area_id':serviceAreaId}).eq('id',r.user!.id);return AppUser(id:r.user!.id,fullName:name,phone:phone,email:email,role:AppRole.customer,serviceAreaId:serviceAreaId);}catch(e){_throw(e);}}
  @override Future<AppUser> registerMerchant(MerchantRegistration r)async{try{final auth=await service.signUp(email:r.email,password:r.password,data:{'full_name':r.ownerName,'phone':r.phone});if(auth.user==null)throw const RepositoryException('فشل إنشاء حساب التاجر');await _db.rpc('submit_merchant_application',params:{'p_owner_name':r.ownerName,'p_phone':r.phone,'p_store_name':r.storeName,'p_category_id':r.categoryId,'p_area_id':r.areaId,'p_address':r.address,'p_whatsapp':r.whatsapp,'p_description':r.description,'p_service_area_ids':r.serviceAreaIds});return AppUser(id:auth.user!.id,fullName:r.ownerName,phone:r.phone,email:r.email,role:AppRole.merchant,status:AccountStatus.pending,serviceAreaId:r.areaId);}catch(e){_throw(e);}}
  @override Future<void> resetPassword(String email)async{try{await service.resetPassword(email);}catch(e){_throw(e);}}
  @override Future<void> signOut()=>service.signOut();
  @override Future<List<ServiceArea>> areas()async{try{final rows=await _db.from('service_areas').select().eq('is_active',true).order('sort_order');return rows.map((j)=>ServiceArea(j['id'],j['name_ar'],(j['delivery_fee']as num).toDouble(),(j['minimum_order']as num).toDouble(),j['estimated_delivery_minutes'])).toList();}catch(e){_throw(e);}}
  @override Future<List<StoreCategory>> storeCategories()async{try{final rows=await _db.from('store_categories').select().eq('is_active',true).order('sort_order');return rows.map((j)=>StoreCategory(j['id'],j['name_ar'],'🏪')).toList();}catch(e){_throw(e);}}
  StoreData _store(Map<String,dynamic>j)=>StoreData(id:j['id'],ownerId:j['owner_id'],categoryId:j['category_id'],name:j['name_ar'],description:j['description']??'',phone:j['phone']??'',whatsapp:j['whatsapp'],address:j['address']??'',areaId:j['service_area_id'],serviceAreaIds:(j['store_service_areas']as List? ??[]).map((x)=>x['service_area_id']as String).toList(),isOpen:j['is_open_manual']??false,isActive:j['is_active']??false,deliveryFee:(j['delivery_fee']as num? ??0).toDouble(),minimumOrder:(j['minimum_order']as num? ??0).toDouble(),deliveryMinutes:j['estimated_delivery_minutes']??45,rating:(j['average_rating']as num? ??0).toDouble(),ratingsCount:j['ratings_count']??0,approval:StoreApproval.values.byName(j['approval_status']??'pending'),subscription:SubscriptionStatus.values.byName(j['subscription_status']??'expired'),rejectionReason:j['rejection_reason'],logoUrl:j['logo_url'],coverUrl:j['cover_url']);
  @override Future<List<StoreData>> stores({required String areaId,String? categoryId,String query='',bool openOnly=false})async{try{var q=_db.from('stores').select('*,store_service_areas!inner(service_area_id)').eq('store_service_areas.service_area_id',areaId);if(categoryId!=null)q=q.eq('category_id',categoryId);if(openOnly)q=q.eq('is_open_manual',true);if(query.trim().isNotEmpty)q=q.ilike('name_ar','%${query.trim()}%');final rows=await q.order('average_rating',ascending:false).limit(50);return rows.map(_store).toList();}catch(e){_throw(e);}}
  @override Future<StoreData?> store(String id)async{try{final j=await _db.from('stores').select('*,store_service_areas(service_area_id)').eq('id',id).maybeSingle();return j==null?null:_store(j);}catch(e){_throw(e);}}
  ProductData _product(Map<String,dynamic>j){final groups=(j['product_option_groups']as List? ??[]).map((g)=>ProductOptionGroup(g['id'],g['name_ar'],(g['product_options']as List? ??[]).map((o)=>ProductOption(o['id'],o['name_ar'],extra:(o['additional_price']as num? ??0).toDouble(),available:o['is_available']??true)).toList(),required:g['is_required']??false,multiple:g['selection_type']=='multiple')).toList();return ProductData(id:j['id'],storeId:j['store_id'],categoryId:j['store_category_id']??j['category_id']??'',name:j['name_ar']??j['name']??'',description:j['description']??'',price:(j['price']as num).toDouble(),compareAtPrice:(j['compare_at_price']as num?)?.toDouble(),stock:j['stock_quantity']??0,available:j['is_available']??false,featured:j['is_featured']??false,imageUrl:j['image_url']??j['thumbnail'],unit:j['unit']??'قطعة',optionGroups:groups);}
  @override Future<List<ProductData>> products(String storeId,{String query=''})async{try{var q=_db.from('products').select('*,product_option_groups(*,product_options(*))').eq('store_id',storeId).isFilter('deleted_at',null);if(query.trim().isNotEmpty)q=q.ilike('name_ar','%${query.trim()}%');final rows=await q.order('created_at',ascending:false).limit(100);return rows.map(_product).toList();}catch(e){_throw(e);}}
  @override Future<List<CustomerAddress>> addresses()async{try{final rows=await _db.from('customer_addresses').select().order('is_default',ascending:false);return rows.map((j)=>CustomerAddress(id:j['id'],title:j['title'],name:j['recipient_name'],phone:j['phone'],areaId:j['service_area_id'],street:[j['street'],j['building_number']].whereType<String>().join('، '),landmark:j['landmark']??'',isDefault:j['is_default']??false)).toList();}catch(e){_throw(e);}}
  @override Future<CustomerAddress> addAddress(CustomerAddress a)async{try{final j=await _db.from('customer_addresses').insert({'user_id':service.currentUser!.id,'title':a.title,'recipient_name':a.name,'phone':a.phone,'service_area_id':a.areaId,'street':a.street,'landmark':a.landmark,'is_default':a.isDefault}).select().single();return CustomerAddress(id:j['id'],title:j['title'],name:j['recipient_name'],phone:j['phone'],areaId:j['service_area_id'],street:j['street'],landmark:j['landmark']??'',isDefault:j['is_default']);}catch(e){_throw(e);}}
  static const _cartKey='souq_derb_cart';
  @override Future<List<CartLine>> cart()async{final raw=_prefs.getString(_cartKey);if(raw==null)return[];try{final data=(jsonDecode(raw)as List).cast<Map<String,dynamic>>();if(data.isEmpty)return[];final ids=data.map((e)=>e['productId']as String).toList();final rows=await _db.from('products').select('*,product_option_groups(*,product_options(*))').inFilter('id',ids);final products=rows.map(_product).toList();return data.map((row){final p=products.firstWhere((x)=>x.id==row['productId']);final optionIds=(row['optionIds']as List? ??[]).cast<String>();return CartLine(product:p,quantity:row['quantity'],options:p.optionGroups.expand((g)=>g.options).where((o)=>optionIds.contains(o.id)).toList(),note:row['note']??'');}).toList();}catch(e){await _prefs.remove(_cartKey);return[];}}
  @override Future<void> saveCart(List<CartLine> lines)async{await _prefs.setString(_cartKey,jsonEncode(lines.map((e)=>e.toJson()).toList()));}
  OrderData _order(Map<String,dynamic>j)=>OrderData(id:j['id'],number:'SD-${j['order_number']}',customerId:j['customer_id']??j['user_id'],storeId:j['store_id'],address:j['customer_addresses']?['street']??'',items:(j['order_items']as List? ??[]).map((x)=>OrderLine(x['product_name_snapshot']??x['product_name'],x['quantity'],(x['unit_price']??x['price']as num).toDouble(),(x['order_item_options']as List? ??[]).map((o)=>ProductOption(o['id']??o['option_name_snapshot'],o['option_name_snapshot'],extra:(o['option_price']as num).toDouble())).toList())).toList(),status:OrderStatus.values.byName((j['status']as String).replaceAll('out_for_delivery','outForDelivery')),subtotal:(j['subtotal']as num).toDouble(),deliveryFee:(j['delivery_fee']??j['shipping_cost']as num).toDouble(),total:(j['total_amount']??j['total']as num).toDouble(),createdAt:DateTime.parse(j['created_at']),reason:j['rejection_reason']??j['cancellation_reason'],note:j['customer_note']);
  @override Future<OrderData> checkout({required String storeId,required CustomerAddress address,required List<CartLine> lines,required String idempotencyKey,String? note})async{try{final result=await _db.rpc('create_souq_order',params:{'p_store_id':storeId,'p_address_id':address.id,'p_items':lines.map((l)=>{'product_id':l.product.id,'quantity':l.quantity,'option_ids':l.options.map((o)=>o.id).toList(),'notes':l.note}).toList(),'p_idempotency_key':idempotencyKey,'p_customer_note':note});final id=result['order_id'];final j=await _db.from('orders').select('*,customer_addresses(street),order_items(*,order_item_options(*))').eq('id',id).single();return _order(j);}catch(e){_throw(e);}}
  Future<List<OrderData>> _ordersQuery(dynamic query)async{try{final rows=await query.select('*,customer_addresses(street),order_items(*,order_item_options(*))').order('created_at',ascending:false);return rows.map<OrderData>((j)=>_order(j)).toList();}catch(e){_throw(e);}}
  @override Future<List<OrderData>> customerOrders()=>_ordersQuery(_db.from('orders'));
  @override Future<List<OrderData>> merchantOrders(String storeId)async{try{final rows=await _db.from('orders').select('*,customer_addresses(street),order_items(*,order_item_options(*))').eq('store_id',storeId).order('created_at',ascending:false);return rows.map<OrderData>((j)=>_order(j)).toList();}catch(e){_throw(e);}}
  @override Future<OrderData> transitionOrder(String id,OrderStatus status,{String? reason})async{try{final name=status==OrderStatus.outForDelivery?'out_for_delivery':status.name;await _db.rpc('transition_souq_order',params:{'p_order_id':id,'p_status':name,'p_reason':reason});final j=await _db.from('orders').select('*,customer_addresses(street),order_items(*,order_item_options(*))').eq('id',id).single();return _order(j);}catch(e){_throw(e);}}
  @override Future<StoreData?> merchantStore()async{try{final j=await _db.from('stores').select('*,store_service_areas(service_area_id)').eq('owner_id',service.currentUser!.id).maybeSingle();return j==null?null:_store(j);}catch(e){_throw(e);}}
  @override Future<StoreData> updateStore(StoreData s)async{try{final j=await _db.from('stores').update({'name_ar':s.name,'description':s.description,'phone':s.phone,'whatsapp':s.whatsapp,'address':s.address,'is_open_manual':s.isOpen,'delivery_fee':s.deliveryFee,'minimum_order':s.minimumOrder,'estimated_delivery_minutes':s.deliveryMinutes,'approval_status':s.approval.name}).eq('id',s.id).select('*,store_service_areas(service_area_id)').single();return _store(j);}catch(e){_throw(e);}}
  @override Future<List<ProductData>> merchantProducts(String storeId)=>products(storeId);
  @override Future<ProductData> saveProduct(ProductData p)async{try{final data={'store_id':p.storeId,'name_ar':p.name,'name':p.name,'description':p.description,'price':p.price,'stock_quantity':p.stock,'stock':p.stock,'is_available':p.available,'is_active':true,'unit':p.unit};final j=p.id.startsWith('p-')?await _db.from('products').insert(data).select().single():await _db.from('products').update(data).eq('id',p.id).select().single();return _product({...j,'product_option_groups':[]});}catch(e){_throw(e);}}
  @override Future<void> deleteProduct(String id)async{try{await _db.from('products').update({'deleted_at':DateTime.now().toIso8601String(),'is_available':false}).eq('id',id);}catch(e){_throw(e);}}
  @override Future<List<StoreData>> storeApplications()async{try{final rows=await _db.from('stores').select('*,store_service_areas(service_area_id)').neq('approval_status','approved').order('created_at');return rows.map(_store).toList();}catch(e){_throw(e);}}
  @override Future<StoreData> reviewStore(String id,StoreApproval status,{String? reason})async{try{final j=await _db.from('stores').update({'approval_status':status.name,'rejection_reason':reason}).eq('id',id).select('*,store_service_areas(service_area_id)').single();return _store(j);}catch(e){_throw(e);}}
  @override Future<StoreData> setSubscription(String id,SubscriptionStatus status)async{try{final j=await _db.from('stores').update({'subscription_status':status.name,'subscription_started_at':DateTime.now().toIso8601String(),'subscription_expires_at':DateTime.now().add(const Duration(days:30)).toIso8601String()}).eq('id',id).select('*,store_service_areas(service_area_id)').single();return _store(j);}catch(e){_throw(e);}}
}
